style.css:
@-moz-document regexp("https?://([a-z0-9-]+\.)?roblox\.com/.*") {
html, body, #container, .rbx-body, .site, .content, .page {
    background: url("https://www.chromethemer.com/wallpapers/chromebook-wallpapers/images/960/nezuko-chromebook-wallpaper.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
    background-color: transparent !important;
  }

  header, footer, .container, .content, .navbar, .site-footer, .site-header {
    background: rgba(255,255,255,0.85) !important;
    backdrop-filter: blur(4px) !important;
  }

  html::before {
    content: "";
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,0.25);
    pointer-events: none;
    z-index: 0;
  }
  body > * { position: relative; z-index: 1; }
}
